  function footprintContains(nx,ny,shape){if(nx<0||nx>1||ny<0||ny>1)return false;if(shape==='courtyard'&&nx>.375+1e-9&&nx<.625-1e-9&&ny>.30+1e-9&&ny<.70-1e-9)return false;const p=normalizedShapePoints(shape);let inside=false;for(let i=0,j=p.length-1;i<p.length;j=i++){const xi=p[i][0],yi=p[i][1],xj=p[j][0],yj=p[j][1];const intersect=((yi>ny)!==(yj>ny))&&(nx<(xj-xi)*(ny-yi)/(yj-yi+1e-12)+xi);if(intersect)inside=!inside;}return inside;}
